(async()=>{
'use strict';
const API='https://api.wiseoldman.net/v2';
const TEMPLE='https://templeosrs.com/api/collection-log';
const PRICES='https://prices.runescape.wiki/api/v1/osrs/latest';
// Reuse the exact five portrait data URIs from the last verified v19 build.
// This is a local static asset read only; it never refreshes WOM or Temple data.
let _portraitSource='';
try{_portraitSource=await fetch('assets/portrait-source.txt').then(r=>{if(!r.ok)throw new Error(`portrait source ${r.status}`);return r.text()})}catch(e){console.warn('Portrait source unavailable; using image-file fallbacks.',e)}
function portraitFromV19(key,fallback){
 const marker=`{key:'${key}'`,i=_portraitSource.indexOf(marker);if(i<0)return fallback;
 const tag="portrait:'",j=_portraitSource.indexOf(tag,i);if(j<0)return fallback;
 const a=j+tag.length,b=_portraitSource.indexOf("'",a);return b>a?_portraitSource.slice(a,b):fallback;
}
const PLAYERS=[
 {key:'dikste',name:'Dikste',core:true,color:'#a99bb8',portrait:portraitFromV19('dikste','img/dikste.webp'),role:'Technical learner · quick on new bosses',mantra:'Wilderness tolerance: zero'},
 {key:'big dog aura',name:'Big Dog Aura',core:true,color:'#e6ad43',portrait:portraitFromV19('big dog aura','img/bigdog.webp'),role:'The Founder · strategist with good clicks',mantra:'Wilderness tolerance: too high.'},
 {key:'lijpste',name:'Lijpste',core:true,color:'#d94ff0',portrait:portraitFromV19('lijpste','img/lijpste.webp'),role:'The total package · progression pusher',mantra:'Spooned again. Complaint pending.'},
 {key:'poep aura',name:'Poep Aura',core:false,color:'#d77878',portrait:portraitFromV19('poep aura','img/poep-aura.png'),role:'Supporting cast',mantra:'WOM + Temple tracked in the background.'},
 {key:'lompste',name:'Lompste',core:false,color:'#d3b35d',portrait:portraitFromV19('lompste','img/lompste.png'),role:'Supporting cast',mantra:'WOM tracked · Collection Log joins automatically after Temple sync.'}
];
const CORE=PLAYERS.filter(p=>p.core),SIDE=PLAYERS.filter(p=>!p.core);
const PERIODS={7:'1 week',30:'1 month',90:'3 months',180:'6 months',365:'1 year'};
const WKEY='ug-v20-wom-cache',TKEY='ug-v20-temple-cache',HKEY='ug-v20-history-cache',CKEY='ug-v20-chronicle-cache';
const state={profiles:{},gains:{},snapshots:{},achievements:{},temple:null,period:365,mode:'gain',prices:null,priceStatus:'idle'};
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const fmt=n=>Number.isFinite(+n)?Math.round(+n).toLocaleString('en-GB'):'—';
const fmt1=n=>Number.isFinite(+n)?(+n).toLocaleString('en-GB',{maximumFractionDigits:1}):'—';
const compact=n=>{n=+n;if(!Number.isFinite(n))return'—';const a=Math.abs(n);if(a>=1e9)return(n/1e9).toFixed(a>=1e10?1:2).replace(/\.0+$/,'')+'B';if(a>=1e6)return(n/1e6).toFixed(a>=1e7?1:2).replace(/\.0+$/,'')+'M';if(a>=1e3)return(n/1e3).toFixed(a>=1e4?1:2).replace(/\.0+$/,'')+'K';return fmt(n)};
const money=n=>{n=+n;if(!Number.isFinite(n))return'—';if(n>=1e9)return(n/1e9).toFixed(2)+'b gp';if(n>=1e6)return(n/1e6).toFixed(1)+'m gp';if(n>=1e3)return(n/1e3).toFixed(1)+'k gp';return fmt(n)+' gp'};
const nice=s=>String(s||'').replace(/_/g,' ').replace(/\b\w/g,m=>m.toUpperCase()).replace(/Of /g,'of ').replace(/The /g,'the ');
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const dateOnly=x=>{const d=new Date(x);return Number.isNaN(+d)?'—':d.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'})};
const dateTime=x=>{const d=new Date(x);return Number.isNaN(+d)?'—':d.toLocaleString('en-GB',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'})};
function loadJSON(k){try{return JSON.parse(localStorage.getItem(k)||'null')}catch{return null}}
function saveJSON(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}}
async function fetchJSON(url,{attempts=2,signal,options={}}={}){let last;for(let i=0;i<attempts;i++){try{const r=await fetch(url,{headers:{Accept:'application/json',...(options.headers||{})},signal,...options});if(r.ok)return r.json();const e=new Error(`HTTP ${r.status}`);e.status=r.status;last=e;if(r.status!==429&&r.status<500)throw e;const ra=+r.headers.get('Retry-After');await sleep(ra>0?ra*1000:650*(i+1));}catch(e){last=e;if(signal?.aborted)throw e;if(i===attempts-1)throw e;await sleep(500*(i+1))}}throw last}
async function staticJSON(path){const r=await fetch(path,{cache:'no-store',headers:{Accept:'application/json'}});if(!r.ok)throw new Error(`HTTP ${r.status}`);return r.json()}
function snapData(key){return state.profiles[key]?.latestSnapshot?.data||state.profiles[key]?.latest_snapshot?.data||null}
function overall(key){return snapData(key)?.skills?.overall||{}}
function currentBoss(key,b){const k=+snapData(key)?.bosses?.[b]?.kills;return Number.isFinite(k)&&k>=0?k:null}
function currentComputed(key,k){const v=+snapData(key)?.computed?.[k]?.value;return Number.isFinite(v)?v:+state.profiles[key]?.[k]||0}
function playerByKey(k){return PLAYERS.find(p=>p.key===k)}
function playerKey(name){const s=String(name||'').toLowerCase();return PLAYERS.find(p=>p.key===s||p.name.toLowerCase()===s)?.key}
function rankValues(vals){const pairs=vals.map((v,i)=>({v:+v,i})).filter(x=>Number.isFinite(x.v)).sort((a,b)=>b.v-a.v);const ranks=Array(vals.length).fill(0);let last=null,rank=0;pairs.forEach((x,pos)=>{if(last===null||x.v!==last)rank=pos+1;ranks[x.i]=rank;last=x.v});return ranks}
function ordinal(r){return r===1?'1st':r===2?'2nd':r===3?'3rd':r===4?'4th':r===5?'5th':`${r}th`}
function rankCell(v,rank,sub=''){return `<td class="${rank?`rank-${rank}`:''}"><b>${esc(v)}</b>${sub?`<small class="cell-sub">${esc(sub)}</small>`:''}${rank?`<span class="rank-chip">${ordinal(rank)}</span>`:''}</td>`}
function setNotice(msg,kind=''){const n=$('#pageNotice');if(n)n.innerHTML=msg?`<div class="notice ${kind}">${msg}</div>`:''}
function applyWomDoc(doc){if(!doc?.profiles)return false;state.profiles=doc.profiles||{};state.gains=doc.gains||{};state.snapshots=doc.snapshots||doc.history||{};state.achievements=doc.achievements||{};return true}
async function loadWomSaved(){let shared=null;try{shared=await staticJSON('data/wom-cache.json')}catch(e){console.warn('shared WOM cache',e)}const local=loadJSON(WKEY);const st=+(shared?.fetchedAt||0),lt=+(local?.fetchedAt||local?.savedAt||0);const chosen=lt>st&&local?.profiles?local:shared;if(chosen&&applyWomDoc(chosen)){saveJSON(WKEY,{...chosen,savedAt:chosen.fetchedAt||chosen.savedAt||Date.now()});return lt>st?'newer browser snapshot':'shared saved snapshot'}if(local&&applyWomDoc(local))return'browser fallback';return'no saved WOM data'}
function validTemple(x){if(!x||typeof x!=='object'||x.error||x.errors)return false;const d=x.data??x;return !!(d&&typeof d==='object'&&d.items&&typeof d.items==='object')}
async function loadTempleSaved({discardBrowser=false}={}){if(discardBrowser){try{localStorage.removeItem(TKEY)}catch(e){}}let shared=null;try{shared=await staticJSON('data/temple-clog.json')}catch(e){console.warn('shared Temple cache',e)}const local=discardBrowser?null:loadJSON(TKEY);const st=+(shared?.fetchedAt||0),lt=+(local?.fetchedAt||local?.savedAt||0);state.temple=(lt>st&&local?.players)?local:(shared?.players?shared:local);return state.temple}
function templePlayers(){return state.temple?.players||{}}
function syncedKeys(){return PLAYERS.map(p=>p.key).filter(k=>validTemple(templePlayers()[k]))}
function templeItemsFor(key){const p=templePlayers()[key];if(!validTemple(p))return[];const d=p.data??p,root=d.items||{};const out=[],seen=new Set();function walk(n,cat=''){if(Array.isArray(n)){for(const v of n)walk(v,cat);return}if(!n||typeof n!=='object')return;if(Number.isFinite(+n.id)){const id=+n.id,count=Math.max(0,+(n.count??n.quantity??0)),sig=`${id}:${cat}`;if(!seen.has(sig)){out.push({...n,id,count,_category:cat||n.category||''});seen.add(sig)}return}for(const [k,v] of Object.entries(n)){const next=cat||(!/^\d+$/.test(k)?k:'');walk(v,next)}}walk(root);return out}
function templeRecent(){let r=state.temple?.recent||state.temple?.recent_items||[];if(!Array.isArray(r)){if(r?.data)r=Array.isArray(r.data)?r.data:Object.values(r.data);else r=Object.values(r||{})}return r.filter(Boolean).map(x=>({id:+x.id,name:x.name||`Item ${x.id}`,player:x.player_name_with_capitalization||x.player||x.username,date:x.date_unix?+x.date_unix*1000:(x.date?+new Date(x.date):0),notable:!!(x.notable_item??x.notable)})).filter(x=>x.id&&x.date).sort((a,b)=>b.date-a.date)}
function normalizeCatalog(){const map=new Map(),raw=state.temple?.catalog||state.temple?.items_catalog||state.temple?.all_items;const add=(id,name,cat='')=>{id=+id;if(!id)return;const old=map.get(id)||{id,name:`Item ${id}`,categories:new Set()};if(name&&String(name)!=='[object Object]')old.name=String(name);if(cat)old.categories.add(nice(cat));map.set(id,old)};if(Array.isArray(raw)){raw.forEach(x=>{if(typeof x==='number')add(x);else if(x&&typeof x==='object')add(x.id??x.item_id,x.name??x.item_name,x.category??x.tab)})}else if(raw&&typeof raw==='object'){for(const [k,v] of Object.entries(raw)){if(typeof v==='string')add(k,v);else if(v&&typeof v==='object')add(v.id??k,v.name??v.item_name,v.category??v.tab)}}for(const k of syncedKeys())for(const it of templeItemsFor(k))add(it.id,it.name,it._category);const cats=state.temple?.categories?.data??state.temple?.categories;if(cats&&typeof cats==='object'){const scan=(n,label='')=>{if(Array.isArray(n)){for(const v of n){if(Number.isFinite(+v))add(v,null,label);else if(v&&typeof v==='object'&&Number.isFinite(+(v.id??v.item_id)))add(v.id??v.item_id,v.name,label)}return}if(!n||typeof n!=='object')return;for(const [k,v] of Object.entries(n)){if(/^\d+$/.test(k)&&typeof v==='string')add(k,v,label);else scan(v,label||k)}};scan(cats)}return map}
function templeCoverage(){const keys=syncedKeys();return{synced:keys.length,total:5,keys,unsynced:PLAYERS.filter(p=>!keys.includes(p.key)).map(p=>p.name)}}
function collectionModel(){const catalog=normalizeCatalog(),keys=syncedKeys(),byPlayer={};for(const p of PLAYERS)byPlayer[p.key]=new Map();for(const k of keys)for(const it of templeItemsFor(k)){const old=byPlayer[k].get(it.id)||{count:0,date:null};old.count=Math.max(old.count,+it.count||0);old.date=it.date||old.date;byPlayer[k].set(it.id,old)}const rows=[];const ids=new Set(catalog.keys());keys.forEach(k=>byPlayer[k].forEach((v,id)=>ids.add(id)));for(const id of ids){const cat=catalog.get(id)||{id,name:`Item ${id}`,categories:new Set()};const counts={},owners={};for(const p of PLAYERS){const rec=byPlayer[p.key].get(id);counts[p.key]=rec?.count||0;owners[p.key]=keys.includes(p.key)?counts[p.key]>0:null}const ownerKeys=keys.filter(k=>owners[k]);rows.push({id,name:cat.name,categories:[...(cat.categories||[])],counts,owners,ownerKeys,ownerCount:ownerKeys.length})}const union=rows.filter(r=>r.ownerCount>0),known=Math.max(catalog.size,...keys.map(k=>+(templePlayers()[k]?.data?.total_collections_available||0)),0);return{rows,keys,byPlayer,union,got:union.length,known:known||rows.length}}
function priceFor(id){const p=state.prices?.[String(id)]||state.prices?.[id];if(!p)return 0;const h=+p.high,l=+p.low;if(h>0&&l>0)return(h+l)/2;if(h>0)return h;if(l>0)return l;return 0}
async function ensurePrices(){if(state.priceStatus==='loaded')return true;if(state.priceStatus==='loading')return false;state.priceStatus='loading';try{const j=await fetchJSON(PRICES,{attempts:2});state.prices=j?.data||j||{};state.priceStatus='loaded';return true}catch(e){console.warn('GE prices',e);state.priceStatus='failed';return false}}
function gainPeriodKey(days){return{7:'week',30:'month',365:'year'}[days]}
function snapshotsFor(key){const a=Array.isArray(state.snapshots?.[key])?state.snapshots[key].slice():[];const lp=state.profiles[key]?.latestSnapshot;if(lp?.createdAt&&!a.some(s=>s.id&&s.id===lp.id))a.push(lp);return a.filter(s=>s?.createdAt&&s?.data).sort((a,b)=>new Date(a.createdAt)-new Date(b.createdAt))}
function nearestBefore(arr,t){let best=null;for(const s of arr){if(+new Date(s.createdAt)<=t)best=s;else break}return best||arr[0]}
function derivedGain(key,days){const arr=snapshotsFor(key);if(arr.length<2)return null;const end=arr[arr.length-1],target=+new Date(end.createdAt)-days*864e5,start=nearestBefore(arr,target);if(!start||start===end)return null;const out={skills:{},bosses:{}};const ks=new Set([...Object.keys(start.data?.skills||{}),...Object.keys(end.data?.skills||{})]);for(const k of ks){const a=start.data?.skills?.[k]||{},b=end.data?.skills?.[k]||{};out.skills[k]={experience:{gained:(+b.experience||0)-(+a.experience||0)},level:{gained:(+b.level||0)-(+a.level||0)}}}const bs=new Set([...Object.keys(start.data?.bosses||{}),...Object.keys(end.data?.bosses||{})]);for(const k of bs){const a=Math.max(0,+start.data?.bosses?.[k]?.kills||0),b=Math.max(0,+end.data?.bosses?.[k]?.kills||0);out.bosses[k]={kills:{gained:Math.max(0,b-a)}}}return{data:out,derived:true,start:start.createdAt,end:end.createdAt}}
function gainNode(key){const pk=gainPeriodKey(state.period),saved=pk?state.gains?.[pk]?.[key]:null;return saved?.data?saved:derivedGain(key,state.period)}
function gainXp(p){return +(gainNode(p.key)?.data?.skills?.overall?.experience?.gained||0)}
function gainLevel(p){return +(gainNode(p.key)?.data?.skills?.overall?.level?.gained||0)}
function topGainSkill(p){const s=gainNode(p.key)?.data?.skills||{};let best=null;for(const [k,v] of Object.entries(s)){if(k==='overall')continue;const x=+v?.experience?.gained||0;if(!best||x>best.x)best={k,x}}return best}
async function directRefreshWom(){setNotice('Refreshing all five current stats via WOM because you explicitly requested it. This updates this browser; the owner shared refresh persists data for everyone.','warn');const profiles={...state.profiles};for(const p of PLAYERS){try{try{await fetch(`${API}/players/${encodeURIComponent(p.name)}`,{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json'}})}catch{}await sleep(700);profiles[p.key]=await fetchJSON(`${API}/players/${encodeURIComponent(p.name)}`,{attempts:2})}catch(e){console.warn('WOM refresh',p.name,e)}await sleep(350)}state.profiles=profiles;for(const period of ['week','month','year']){state.gains[period]=state.gains[period]||{};for(const p of CORE){try{state.gains[period][p.key]=await fetchJSON(`${API}/players/${encodeURIComponent(p.name)}/gained?period=${period}`,{attempts:2})}catch{}await sleep(250)}}const doc={fetchedAt:Date.now(),profiles:state.profiles,gains:state.gains,snapshots:state.snapshots,achievements:state.achievements};saveJSON(WKEY,doc);setNotice('WOM refresh finished for this browser. No background refresh loop was enabled.','')}
async function directRefreshTemple(){const btn=$('[data-refresh-temple]');if(btn){btn.disabled=true;btn.textContent='Refreshing Temple…'}setNotice('Refreshing Collection Log via Temple because you explicitly requested it. Existing good data is retained if one member fails.','warn');const old=state.temple||{},players={...(old.players||{})};for(const p of PLAYERS){const q=new URLSearchParams({player:p.name,categories:'all',includenames:'1',includemissingitems:'1',onlyitems:'0',dateformat:'unix'});try{const x=await fetchJSON(`${TEMPLE}/player_collection_log.php?${q}`,{attempts:2});if(validTemple(x))players[p.key]=x}catch(e){console.warn('Temple',p.name,e)}await sleep(350)}let catalog=old.catalog,categories=old.categories;try{const x=await fetchJSON(`${TEMPLE}/items.php`,{attempts:2});catalog=x?.data??x}catch{}try{const x=await fetchJSON(`${TEMPLE}/categories.php`,{attempts:2});categories=x}catch{}const recent=[];for(const p of PLAYERS){try{const q=new URLSearchParams({player:p.name,count:'100'}),x=await fetchJSON(`${TEMPLE}/player_recent_items.php?${q}`,{attempts:2}),d=x?.data??x,rows=Array.isArray(d)?d:Object.values(d||{});for(const row of rows)if(row&&typeof row==='object')recent.push({...row,player:row.player||p.name,player_name_with_capitalization:row.player_name_with_capitalization||p.name})}catch{}await sleep(250)}state.temple={source:'TempleOSRS browser refresh',fetchedAt:Date.now(),players,catalog,categories,recent:recent.length?recent:old.recent||[],groupSize:5};saveJSON(TKEY,state.temple);setNotice(`Temple refresh finished for this browser. ${syncedKeys().length}/5 valid Collection Logs are now known.`,'');renderMast();renderGim();if(btn){btn.disabled=false;btn.textContent='Refresh Collection Log via Temple'}}
function updateDataStatus(source='saved'){const wc=loadJSON(WKEY);const wom=$('[data-wom-status]');if(wom){const b=$('b',wom),d=$('.dot',wom);const at=wc?.fetchedAt||wc?.savedAt;b.textContent=at?`saved ${dateOnly(at)}`:source;d.classList.add(Object.keys(state.profiles).length?'ok':'warn')}const t=$('[data-temple-status]');if(t){const b=$('b',t),d=$('.dot',t),at=state.temple?.fetchedAt||state.temple?.fetched_at;b.textContent=at?`saved ${dateOnly(at)}`:(state.temple?'saved cache':'unavailable');d.classList.add(state.temple?'ok':'warn')}$$('[data-period-status]').forEach(x=>x.textContent=PERIODS[state.period]||`${state.period} days`)}
function bindCommon(){$$('[data-refresh-wom]').forEach(b=>b.onclick=async()=>{b.disabled=true;const old=b.textContent;b.textContent='Refreshing stats…';try{await directRefreshWom();await renderPage()}finally{b.disabled=false;b.textContent=old}});$$('[data-reload-temple]').forEach(b=>b.onclick=async()=>{b.disabled=true;const old=b.textContent;b.textContent='Reloading saved data…';await loadTempleSaved({discardBrowser:true});renderMast();await renderPage();b.disabled=false;b.textContent=old});$$('[data-refresh-temple]').forEach(b=>b.onclick=directRefreshTemple);$$('[data-shared-refresh]').forEach(a=>a.href='https://github.com/MarnixS/fun/actions/workflows/temple-cache.yml');$$('[data-period-button]').forEach(b=>b.onclick=async()=>{state.period=+b.dataset.periodButton;$$('[data-period-button]').forEach(x=>x.classList.toggle('active',+x.dataset.periodButton===state.period));$$('[data-period-copy]').forEach(x=>x.textContent=PERIODS[state.period]);updateDataStatus();await renderPage()});$$('[data-mode]').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;$$('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));renderProgressCharts()})}
function renderMast(){const gs=collectionModel(),cov=templeCoverage(),totalXp=PLAYERS.reduce((n,p)=>n+(+overall(p.key).experience||0),0);$$('[data-mast-log]').forEach(x=>x.textContent=gs.known?`${fmt(gs.got)} / ${fmt(gs.known)}`:'—');$$('[data-mast-log-sub]').forEach(x=>x.textContent=`${cov.synced}/5 Collection Logs synced${cov.unsynced.length?' · '+cov.unsynced.join(', ')+' unsynced':''}`);$$('[data-mast-xp]').forEach(x=>x.textContent=totalXp?compact(totalXp):'—');const dr=templeRecent()[0];$$('[data-mast-drop]').forEach(x=>x.textContent=dr?.name||'No recent feed yet');$$('[data-mast-drop-sub]').forEach(x=>x.textContent=dr?`${dr.player||'Group'} · ${dateOnly(dr.date)} · Temple`:'Temple recent unlocks');$$('[data-mast-drop-icon]').forEach(x=>{if(dr){x.src=`https://static.runelite.net/cache/item/icon/${dr.id}.png`;x.hidden=false}else x.hidden=true});const wAt=loadJSON(WKEY)?.fetchedAt||loadJSON(WKEY)?.savedAt,tAt=state.temple?.fetchedAt;const newest=Math.max(+wAt||0,+tAt||0);$$('[data-mast-refresh]').forEach(x=>x.textContent=newest?dateOnly(newest):'No saved data');$$('[data-mast-refresh-sub]').forEach(x=>x.textContent='WOM + Temple stay saved until you refresh')}
function cardFor(p,side=false){const o=overall(p.key),ehp=currentComputed(p.key,'ehp'),ehb=currentComputed(p.key,'ehb'),raid=['chambers_of_xeric','chambers_of_xeric_challenge_mode','theatre_of_blood','theatre_of_blood_hard_mode','tombs_of_amascut','tombs_of_amascut_expert'].reduce((n,b)=>n+(currentBoss(p.key,b)||0),0),synced=syncedKeys().includes(p.key);if(side)return `<article class="side-card" style="--pc:${p.color}"><img src="${p.portrait}" alt="${p.name}"><div><h3>${p.name}</h3><div class="side-rule">${p.role} · ${synced?'WOM + Temple':'WOM; Collection Log unsynced'}</div><div class="side-stats"><div><span>Total level</span><b>${fmt(o.level)}</b></div><div><span>Total XP</span><b>${compact(o.experience)}</b></div><div><span>EHP / EHB</span><b>${fmt1(ehp)} / ${fmt1(ehb)}</b></div></div><span class="side-badge">${synced?'Collection Log included in current group totals':'Collection Log unknown, not counted as zero'}</span></div></article>`;return `<article class="player-card" style="--pc:${p.color}"><div class="player-card-head"><img class="player-portrait" src="${p.portrait}" alt="${p.name}"><div><h3>${p.name}</h3><div class="player-role">${p.role}</div></div></div><div class="player-mantra">${p.mantra}</div><div class="stat-grid"><div class="stat-box"><span>Total level</span><b>${fmt(o.level)}</b></div><div class="stat-box"><span>Total XP</span><b>${compact(o.experience)}</b></div><div class="stat-box"><span>EHP</span><b>${fmt1(ehp)}</b></div><div class="stat-box"><span>EHB</span><b>${fmt1(ehb)}</b></div><div class="stat-box"><span>Raid KC</span><b>${fmt(raid)}</b></div><div class="stat-box"><span>Saved WOM</span><b class="small-value">${dateOnly(state.profiles[p.key]?.updatedAt||state.profiles[p.key]?.latestSnapshot?.createdAt)}</b></div></div></article>`}
function renderOverview(){const pc=$('#playerCards');if(pc)pc.innerHTML=CORE.map(p=>cardFor(p)).join('');const sc=$('#sideCastGrid');if(sc)sc.innerHTML=SIDE.map(p=>cardFor(p,true)).join('');renderStanding();renderGainCards();renderGimTeaser()}
function renderStanding(){const t=$('#standingTable');if(!t)return;const metrics=[['Total level',p=>+overall(p.key).level||0],['Total XP',p=>+overall(p.key).experience||0],['EHP',p=>currentComputed(p.key,'ehp')],['EHB',p=>currentComputed(p.key,'ehb')],['99s',p=>Object.entries(snapData(p.key)?.skills||{}).filter(([k,v])=>k!=='overall'&&+v.level>=99).length]];let h='<thead><tr><th>Metric</th>'+CORE.map(p=>`<th>${p.name}</th>`).join('')+'</tr></thead><tbody>';for(const [label,fn] of metrics){const vals=CORE.map(fn),r=rankValues(vals);h+=`<tr><td>${label}</td>${vals.map((v,i)=>rankCell(label.includes('XP')?compact(v):label.includes('E')?fmt1(v):fmt(v),r[i])).join('')}</tr>`}t.innerHTML=h+'</tbody>'}
function renderFiveStanding(){const t=$('#fiveStandingTable');if(!t)return;const metrics=[['Total level',p=>+overall(p.key).level||0],['Total XP',p=>+overall(p.key).experience||0],['EHP',p=>currentComputed(p.key,'ehp')],['EHB',p=>currentComputed(p.key,'ehb')]];let h='<thead><tr><th>Metric</th>'+PLAYERS.map(p=>`<th>${p.name}</th>`).join('')+'</tr></thead><tbody>';for(const [label,fn] of metrics){const vals=PLAYERS.map(fn),r=rankValues(vals);h+=`<tr><td>${label}</td>${vals.map((v,i)=>rankCell(label==='Total XP'?compact(v):label.startsWith('E')?fmt1(v):fmt(v),r[i])).join('')}</tr>`}t.innerHTML=h+'</tbody>'}
function renderGainCards(){const host=$('#gainCards');if(!host)return;const vals=CORE.map(gainXp),r=rankValues(vals);host.innerHTML=CORE.map((p,i)=>{const top=topGainSkill(p),node=gainNode(p.key);return `<article class="gain-card rank-${r[i]||3}" style="--pc:${p.color}"><div class="name">${p.name}</div><div class="big">+${compact(vals[i])}</div><small>${PERIODS[state.period]} · ${gainLevel(p)>=0?'+':''}${fmt(gainLevel(p))} total levels${node?.derived?' · derived from saved WOM snapshots':''}</small><div class="top">Top skill: ${top?`<button class="metric-link" data-skill="${top.k}" data-recent="1">${nice(top.k)}</button> · +${compact(top.x)}`:'No saved gain data for this window'}</div></article>`}).join('')}
function renderGimTeaser(){const h=$('#gimTeaser');if(!h)return;const gs=collectionModel(),cov=templeCoverage();h.innerHTML=`<div class="section-head teaser-head"><div><div class="eyebrow">GROUP IRONMAN TRACKER</div><h2>The full five-man group</h2><div class="section-note">All five members are integrated. Core-three comparisons stay the default where that tells the clearest story.</div></div><a class="btn" href="gim.html">Open tracker →</a></div><div class="kpi-grid"><div class="kpi"><span>GIM size</span><b>5</b></div><div class="kpi"><span>WOM tracked</span><b>${PLAYERS.filter(p=>state.profiles[p.key]).length}/5</b></div><div class="kpi"><span>Collection Logs synced</span><b>${cov.synced}/5</b></div><div class="kpi"><span>Current group uniques</span><b>${gs.got?fmt(gs.got):'—'}</b></div></div>`}
function renderHiscores(){renderCurrentSkills();renderCurrentBosses();renderActivities();const side=$('#hiscoreSide');if(side)side.innerHTML=SIDE.map(p=>cardFor(p,true)).join('')}
function renderCurrentSkills(){const t=$('#currentSkillsTable');if(!t)return;const skills=new Set();CORE.forEach(p=>Object.keys(snapData(p.key)?.skills||{}).forEach(k=>{if(k!=='overall')skills.add(k)}));let h='<thead><tr><th>Skill</th>'+CORE.map(p=>`<th>${p.name}</th>`).join('')+'</tr></thead><tbody>';for(const k of skills){const vals=CORE.map(p=>+snapData(p.key)?.skills?.[k]?.experience||0),r=rankValues(vals);h+=`<tr><td><button class="metric-link" data-skill="${k}">${nice(k)}</button></td>${CORE.map((p,i)=>{const x=snapData(p.key)?.skills?.[k]||{};return rankCell(`Lv ${fmt(x.level)} · ${compact(x.experience)} XP`,r[i])}).join('')}</tr>`}t.innerHTML=h+'</tbody>'}
function bossKeys(){const s=new Set();CORE.forEach(p=>Object.keys(snapData(p.key)?.bosses||{}).forEach(k=>{if(CORE.some(q=>(currentBoss(q.key,k)||0)>0))s.add(k)}));return[...s].sort((a,b)=>Math.max(...CORE.map(p=>currentBoss(p.key,b)||0))-Math.max(...CORE.map(p=>currentBoss(p.key,a)||0)))}
function renderCurrentBosses(){const t=$('#bossTable');if(!t)return;let h='<thead><tr><th>Boss</th>'+CORE.map(p=>`<th>${p.name}</th>`).join('')+'</tr></thead><tbody>';for(const k of bossKeys().slice(0,60)){const vals=CORE.map(p=>currentBoss(p.key,k)??0),r=rankValues(vals);h+=`<tr><td>${nice(k)}</td>${vals.map((v,i)=>rankCell(fmt(v),r[i])).join('')}</tr>`}t.innerHTML=h+'</tbody>'}
function activityValue(key,a){const x=snapData(key)?.activities?.[a];const v=+(x?.score??x?.value??x?.kills??-1);return Number.isFinite(v)&&v>=0?v:null}
function renderActivities(){const t=$('#activityTable');if(!t)return;const set=new Set();CORE.forEach(p=>Object.keys(snapData(p.key)?.activities||{}).forEach(k=>{if(CORE.some(q=>(activityValue(q.key,k)??0)>0))set.add(k)}));const rows=[...set].map(k=>({k,vals:CORE.map(p=>activityValue(p.key,k)??0)})).sort((a,b)=>Math.max(...b.vals)-Math.max(...a.vals));let h='<thead><tr><th>Activity</th>'+CORE.map(p=>`<th>${p.name}</th>`).join('')+'</tr></thead><tbody>';for(const row of rows){const ranks=rankValues(row.vals);h+=`<tr><td>${nice(row.k)}</td>${row.vals.map((v,i)=>rankCell(fmt(v),ranks[i])).join('')}</tr>`}t.innerHTML=h+'</tbody>'}
function currentHistory(key,days=state.period){const arr=snapshotsFor(key),end=arr.length?+new Date(arr[arr.length-1].createdAt):Date.now(),start=end-days*864e5;return arr.filter(s=>+new Date(s.createdAt)>=start)}
function lineSeriesFromHistory(metric,kind='skill'){return CORE.map(p=>({name:p.name,color:p.color,data:currentHistory(p.key).map(s=>{let v;if(kind==='skill')v=s.data?.skills?.[metric]?.experience;else if(kind==='level')v=s.data?.skills?.overall?.level;else if(kind==='computed')v=s.data?.computed?.[metric]?.value;else if(kind==='boss')v=s.data?.bosses?.[metric]?.kills;return{date:s.createdAt,value:Number.isFinite(+v)&&+v>=0?+v:null}}).filter(x=>x.value!=null)}))}
function drawLine(host,series,{floorZero=false,format='compact',gainMode=false}={}){if(typeof host==='string')host=$(host);if(!host)return;host.innerHTML='';let ss=series.map(s=>({...s,data:s.data.slice().sort((a,b)=>new Date(a.date)-new Date(b.date))}));if(gainMode)ss=ss.map(s=>{if(!s.data.length)return s;const base=s.data[0].value;return{...s,data:s.data.map(x=>({...x,value:x.value-base}))}});const all=ss.flatMap(s=>s.data).filter(x=>Number.isFinite(+x.value));if(!all.length){host.innerHTML='<div class="chart-empty">No saved WOM datapoints for this view. Use the owner shared refresh once if you want to extend stored history.</div>';return}const W=900,H=300,p={l:62,r:18,t:16,b:36},xs=all.map(x=>+new Date(x.date)),ys=all.map(x=>+x.value);let minX=Math.min(...xs),maxX=Math.max(...xs);if(minX===maxX)maxX+=864e5;let minY=floorZero?0:Math.min(...ys),maxY=Math.max(...ys);if(gainMode)minY=Math.min(0,minY);if(maxY===minY)maxY=minY+1;const span=maxY-minY;if(!floorZero)minY-=span*.06;maxY+=span*.08;const X=t=>p.l+(t-minX)/Math.max(1,maxX-minX)*(W-p.l-p.r),Y=v=>p.t+(maxY-v)/Math.max(1,maxY-minY)*(H-p.t-p.b),ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox',`0 0 ${W} ${H}`);for(let i=0;i<5;i++){const yy=p.t+i*(H-p.t-p.b)/4,v=maxY-i*(maxY-minY)/4,ln=document.createElementNS(ns,'line');Object.entries({x1:p.l,x2:W-p.r,y1:yy,y2:yy,stroke:'#3a2d1d'}).forEach(([k,z])=>ln.setAttribute(k,z));svg.append(ln);const tx=document.createElementNS(ns,'text');tx.setAttribute('x',p.l-7);tx.setAttribute('y',yy+4);tx.setAttribute('text-anchor','end');tx.setAttribute('fill','#8f8069');tx.setAttribute('font-size','10');tx.textContent=format==='hours'?fmt1(v):compact(v);svg.append(tx)}for(let i=0;i<5;i++){const xx=p.l+i*(W-p.l-p.r)/4,t=minX+i*(maxX-minX)/4,tx=document.createElementNS(ns,'text');tx.setAttribute('x',xx);tx.setAttribute('y',H-9);tx.setAttribute('text-anchor',i===0?'start':i===4?'end':'middle');tx.setAttribute('fill','#8f8069');tx.setAttribute('font-size','9');tx.textContent=new Date(t).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:(maxX-minX)>300*864e5?'2-digit':undefined});svg.append(tx)}ss.forEach(s=>{if(!s.data.length)return;const path=document.createElementNS(ns,'path');path.setAttribute('d',s.data.map((d,i)=>(i?'L':'M')+X(+new Date(d.date)).toFixed(1)+' '+Y(+d.value).toFixed(1)).join(' '));path.setAttribute('fill','none');path.setAttribute('stroke',s.color);path.setAttribute('stroke-width','2.8');path.setAttribute('stroke-linejoin','round');svg.append(path)});host.append(svg)}
async function renderProgress(){renderGainCards();renderProgressCharts();renderProgressSelectors();renderSkillGainTable();renderBossGainTable()}
function renderProgressCharts(){if(!$('#xpChart'))return;drawLine('#xpChart',lineSeriesFromHistory('overall','skill'),{gainMode:state.mode==='gain'});drawLine('#levelChart',lineSeriesFromHistory('overall','level'),{gainMode:state.mode==='gain'});drawLine('#ehpChart',lineSeriesFromHistory('ehp','computed'),{format:'hours',gainMode:state.mode==='gain'});drawLine('#ehbChart',lineSeriesFromHistory('ehb','computed'),{format:'hours',gainMode:state.mode==='gain'});const sk=$('#skillSelect')?.value;if(sk){$('#skillChartTitle').textContent=nice(sk)+' XP';drawLine('#skillChart',lineSeriesFromHistory(sk,'skill'),{gainMode:state.mode==='gain'})}const bk=$('#bossSelect')?.value;if(bk){$('#bossChartTitle').textContent=nice(bk)+' KC';drawLine('#bossChart',lineSeriesFromHistory(bk,'boss'),{floorZero:true,gainMode:state.mode==='gain'})}}
function renderProgressSelectors(){const ss=$('#skillSelect'),bs=$('#bossSelect');if(ss&&!ss.options.length){const ks=Object.keys(snapData(CORE[0].key)?.skills||{}).filter(k=>k!=='overall');ss.innerHTML=ks.map(k=>`<option value="${k}">${nice(k)}</option>`).join('');ss.onchange=renderProgressCharts}if(bs&&!bs.options.length){const ks=bossKeys();bs.innerHTML=ks.map(k=>`<option value="${k}">${nice(k)}</option>`).join('');bs.onchange=renderProgressCharts}renderProgressCharts()}
function skillGain(key,skill){return +(gainNode(key)?.data?.skills?.[skill]?.experience?.gained||0)}
function renderSkillGainTable(){const t=$('#skillGainTable');if(!t)return;const ks=new Set();CORE.forEach(p=>Object.keys(gainNode(p.key)?.data?.skills||{}).forEach(k=>{if(k!=='overall')ks.add(k)}));let h='<thead><tr><th>Skill</th>'+CORE.map(p=>`<th>${p.name}</th>`).join('')+'</tr></thead><tbody>';for(const k of ks){const vals=CORE.map(p=>skillGain(p.key,k)),r=rankValues(vals);h+=`<tr><td><button class="metric-link" data-skill="${k}" data-recent="1">${nice(k)}</button></td>${vals.map((v,i)=>rankCell('+'+compact(v),r[i])).join('')}</tr>`}t.innerHTML=h+'</tbody>'}
function renderBossGainTable(){const t=$('#bossGainTable');if(!t)return;const ks=new Set();CORE.forEach(p=>Object.keys(gainNode(p.key)?.data?.bosses||{}).forEach(k=>ks.add(k)));const rows=[...ks].map(k=>({k,vals:CORE.map(p=>Math.max(0,+(gainNode(p.key)?.data?.bosses?.[k]?.kills?.gained||0)))})).filter(r=>r.vals.some(v=>v>0)).sort((a,b)=>Math.max(...b.vals)-Math.max(...a.vals));let h='<thead><tr><th>Boss</th>'+CORE.map(p=>`<th>${p.name}</th>`).join('')+'</tr></thead><tbody>';for(const row of rows){const ranks=rankValues(row.vals);h+=`<tr><td>${nice(row.k)}</td>${row.vals.map((v,i)=>rankCell('+'+fmt(v),ranks[i])).join('')}</tr>`}t.innerHTML=h+'</tbody>'}
let clogPage=0;
function rowValue(row){let n=0;for(const k of syncedKeys())n+=priceFor(row.id)*(row.counts[k]||0);return n}
function renderGim(){const m=collectionModel(),cov=templeCoverage(),k=$('#gimKpis');if(k)k.innerHTML=`<div class="kpi"><span>Current group uniques</span><b>${fmt(m.got)}</b><small>union of synced Temple logs</small></div><div class="kpi"><span>Collection Log items</span><b>${fmt(m.known)}</b><small>Temple catalogue</small></div><div class="kpi"><span>Collection Logs synced</span><b>${cov.synced}/5</b><small>${cov.unsynced.length?esc(cov.unsynced.join(', ')+' unknown'):'all five synced'}</small></div><div class="kpi"><span>Missing among synced logs</span><b>${fmt(Math.max(0,m.known-m.got))}</b><small>unsynced members are not treated as zero</small></div>`;const bar=$('#gimProgress');if(bar&&m.known)bar.style.width=Math.min(100,100*m.got/m.known)+'%';renderGimMembers(m);renderFiveStanding();renderClogSummary(m);renderClogItems(m);renderClogContribution(m);renderClogOverlap(m);renderClogCategories(m);renderDrops();bindGimTabs();bindRecovery()}
function renderGimMembers(m=collectionModel()){const h=$('#gimMembers');if(!h)return;h.innerHTML=PLAYERS.map(p=>{const synced=m.keys.includes(p.key),count=synced?m.byPlayer[p.key].size:null,got=synced?[...m.byPlayer[p.key].values()].filter(x=>x.count>0).length:null;return `<div class="kpi ${p.core?'':'side-kpi'}"><span>${p.name}${p.core?'':' · supporting cast'}</span><b>${synced?fmt(got):'not synced'}</b><small>${synced?'personal obtained uniques':'Collection Log unknown'}</small></div>`}).join('')}
function renderClogSummary(m=collectionModel()){const h=$('#clogSummary');if(!h)return;const exclusive=m.union.filter(r=>r.ownerCount===1).length,shared=m.union.filter(r=>r.ownerCount>=2).length,all=m.keys.length?m.union.filter(r=>r.ownerCount===m.keys.length).length:0;h.innerHTML=`<div class="kpi"><span>Group uniques now</span><b>${fmt(m.got)}</b><small>status quo</small></div><div class="kpi"><span>Exclusive uniques</span><b>${fmt(exclusive)}</b><small>only one synced member has it</small></div><div class="kpi"><span>Shared uniques</span><b>${fmt(shared)}</b><small>2+ synced members</small></div><div class="kpi"><span>Owned by every synced member</span><b>${fmt(all)}</b><small>${m.keys.length} synced logs</small></div>`}
function renderClogItems(m=collectionModel()){const t=$('#clogItemTable');if(!t)return;let arr=m.rows.slice(),q=($('#clogSearch')?.value||'').toLowerCase(),status=$('#clogStatus')?.value||'all',sort=$('#clogSort')?.value||'name';if(q)arr=arr.filter(x=>x.name.toLowerCase().includes(q));if(status==='missing')arr=arr.filter(x=>x.ownerCount===0);if(status==='obtained')arr=arr.filter(x=>x.ownerCount>0);if(status==='exclusive')arr=arr.filter(x=>x.ownerCount===1);if(status==='shared')arr=arr.filter(x=>x.ownerCount>=2);if(sort==='owners')arr.sort((a,b)=>b.ownerCount-a.ownerCount||a.name.localeCompare(b.name));else if(sort==='value'){if(state.priceStatus==='idle')ensurePrices().then(()=>renderClogItems());arr.sort((a,b)=>rowValue(b)-rowValue(a)||a.name.localeCompare(b.name))}else arr.sort((a,b)=>a.name.localeCompare(b.name));const size=100,pages=Math.max(1,Math.ceil(arr.length/size));clogPage=Math.max(0,Math.min(clogPage,pages-1));const show=arr.slice(clogPage*size,(clogPage+1)*size);let h='<thead><tr><th>Item</th>'+PLAYERS.map(p=>`<th>${p.name}</th>`).join('')+'<th>Owners</th><th>Stack value</th></tr></thead><tbody>';for(const x of show){h+=`<tr><td><div class="item-cell"><img src="https://static.runelite.net/cache/item/icon/${x.id}.png" alt=""><span><b>${esc(x.name)}</b>${x.categories.length?`<small>${esc(x.categories.slice(0,2).join(' · '))}</small>`:''}</span></div></td>${PLAYERS.map(p=>m.keys.includes(p.key)?`<td>${x.owners[p.key]?`×${fmt(x.counts[p.key]||1)}`:'—'}</td>`:`<td class="unknown-cell">unknown</td>`).join('')}<td>${x.ownerCount}/${m.keys.length||0}</td><td>${state.priceStatus==='loaded'?money(rowValue(x)):'—'}</td></tr>`}t.innerHTML=h+'</tbody>';const pi=$('#clogPageInfo');if(pi)pi.textContent=`${fmt(arr.length)} matching items · page ${clogPage+1}/${pages}`;const prev=$('#clogPrev'),next=$('#clogNext');if(prev){prev.disabled=clogPage===0;prev.onclick=()=>{clogPage--;renderClogItems()}}if(next){next.disabled=clogPage>=pages-1;next.onclick=()=>{clogPage++;renderClogItems()}}}
function renderClogContribution(m=collectionModel()){const h=$('#clogContribution');if(!h)return;const totalCredit=m.got||1;h.innerHTML=PLAYERS.map(p=>{if(!m.keys.includes(p.key))return `<article class="contrib-card unsynced" style="--pc:${p.color}"><h3>${p.name}</h3><div class="muted">Collection Log not synced · contribution unknown, never zero.</div></article>`;const own=m.union.filter(r=>r.owners[p.key]).length,exclusive=m.union.filter(r=>r.ownerCount===1&&r.owners[p.key]).length,weighted=m.union.reduce((n,r)=>n+(r.owners[p.key]?1/r.ownerCount:0),0),pct=100*weighted/totalCredit;let mv=0,allv=0;if(state.priceStatus==='loaded'){for(const r of m.union){for(const k of m.keys)allv+=priceFor(r.id)*(r.counts[k]||0);mv+=priceFor(r.id)*(r.counts[p.key]||0)}}return `<article class="contrib-card" style="--pc:${p.color}"><h3>${p.name}</h3><div class="contrib-stat"><span>Personal uniques</span><b>${fmt(own)}</b></div><div class="contrib-stat"><span>Group-union coverage</span><b>${m.got?fmt1(100*own/m.got)+'%':'—'}</b></div><div class="contrib-stat"><span>Exclusive group unlocks</span><b>${fmt(exclusive)}</b></div><div class="contrib-stat"><span>Weighted unique credit</span><b>${fmt1(pct)}%</b></div><div class="contrib-bar"><i style="width:${Math.min(100,pct)}%;background:${p.color}"></i></div><div class="contrib-stat"><span>Logged-stack value share</span><b>${state.priceStatus==='loaded'&&allv?fmt1(100*mv/allv)+'%':'open Item value to load'}</b></div></article>`}).join('')}
function renderClogOverlap(m=collectionModel()){const h=$('#clogOverlap');if(!h)return;const dist=Array.from({length:m.keys.length+1},(_,i)=>i).map(n=>[n,m.rows.filter(r=>r.ownerCount===n).length]),pairs=[];for(let i=0;i<m.keys.length;i++)for(let j=i+1;j<m.keys.length;j++){const a=m.keys[i],b=m.keys[j],sa=new Set(m.union.filter(r=>r.owners[a]).map(r=>r.id)),sb=new Set(m.union.filter(r=>r.owners[b]).map(r=>r.id)),shared=[...sa].filter(x=>sb.has(x)).length,union=new Set([...sa,...sb]).size;pairs.push({a,b,shared,union,sim:union?100*shared/union:0})}h.innerHTML=`<div class="overlap-strip">${dist.map(([n,c])=>`<div><b>${fmt(c)}</b><span>${n===0?'missing':n===1?'one owner':`${n} owners`}</span></div>`).join('')}</div><div class="pair-grid">${pairs.map(x=>`<article class="pair-card"><h4>${playerByKey(x.a)?.name} + ${playerByKey(x.b)?.name}</h4><div class="pair-big">${fmt(x.shared)} shared uniques</div><div>${fmt(x.union)} combined uniques · ${fmt1(x.sim)}% similarity</div></article>`).join('')||'<div class="notice">Need at least two synced Collection Logs for overlap analysis.</div>'}</div>`}
async function renderClogValue(m=collectionModel()){const h=$('#clogValue');if(!h)return;if(state.priceStatus!=='loaded'){h.innerHTML='<div class="notice">Loading live OSRS Wiki GE prices for valuation only. WOM/Temple stats remain saved.</div>';const ok=await ensurePrices();if(!ok){h.innerHTML='<div class="notice warn">GE prices could not be loaded. Collection Log ownership remains fully available; unpriced items are treated as 0 gp.</div>';return}}const per={};for(const k of m.keys)per[k]=0;let stacks=0,oneEach=0,rows=[];for(const r of m.union){const p=priceFor(r.id);if(p>0)oneEach+=p;for(const k of m.keys){const v=p*(r.counts[k]||0);per[k]+=v;stacks+=v;if(v>0)rows.push({id:r.id,name:r.name,key:k,count:r.counts[k],value:v})}}rows.sort((a,b)=>b.value-a.value);h.innerHTML=`<div class="value-kpis"><div class="kpi"><span>All logged stacks</span><b>${money(stacks)}</b><small>price × every logged quantity</small></div><div class="kpi"><span>Group one-of-each</span><b>${money(oneEach)}</b><small>one copy of every group unique</small></div><div class="kpi"><span>Unpriced / untradeable</span><b>0 gp</b><small>never estimated</small></div></div><div class="value-member-grid">${PLAYERS.map(p=>`<div class="kpi ${m.keys.includes(p.key)?'':'side-kpi'}"><span>${p.name}</span><b>${m.keys.includes(p.key)?money(per[p.key]):'unknown'}</b><small>${m.keys.includes(p.key)?'logged stack value':'Collection Log unsynced'}</small></div>`).join('')}</div><h3>Highest-value logged stacks</h3><div class="value-list">${rows.slice(0,24).map(r=>`<div class="value-row"><img src="https://static.runelite.net/cache/item/icon/${r.id}.png" alt=""><span><b>${esc(r.name)}</b><small>${playerByKey(r.key)?.name} · ×${fmt(r.count)}</small></span><strong>${money(r.value)}</strong></div>`).join('')}</div>`;renderClogContribution(m);renderClogItems(m)}
function categoryMap(m=collectionModel()){const cats=new Map();for(const r of m.rows){for(const c of r.categories){if(!cats.has(c))cats.set(c,new Set());cats.get(c).add(r.id)}}if(!cats.size){cats.set('All tracked items',new Set(m.rows.map(r=>r.id)))}return cats}
function renderClogCategories(m=collectionModel()){const h=$('#clogCategories');if(!h)return;const cats=[...categoryMap(m)].map(([name,ids])=>({name,ids:[...ids],got:[...ids].filter(id=>m.rows.find(r=>r.id===id)?.ownerCount>0).length})).sort((a,b)=>b.ids.length-a.ids.length);h.innerHTML=cats.slice(0,80).map(c=>`<article class="category-card"><h4>${esc(c.name)}</h4><div class="category-main">${fmt(c.got)} / ${fmt(c.ids.length)}</div><div class="mini-progress"><i style="width:${c.ids.length?100*c.got/c.ids.length:0}%"></i></div><div class="category-members">${PLAYERS.map(p=>m.keys.includes(p.key)?`<span>${p.name}: ${fmt(c.ids.filter(id=>m.rows.find(r=>r.id===id)?.owners[p.key]).length)}</span>`:`<span>${p.name}: unknown</span>`).join('')}</div></article>`).join('')}
function renderDrops(){const h=$('#recentDrops');if(!h)return;const arr=templeRecent().slice(0,60);h.innerHTML=arr.length?arr.map(d=>`<article class="drop-card ${d.notable?'notable':''}"><img src="https://static.runelite.net/cache/item/icon/${d.id}.png" alt=""><div><b>${esc(d.name)}</b><small>${esc(d.player||'Group')} · ${dateOnly(d.date)} · drop/item unlock via Temple${d.notable?' · notable':''}</small></div></article>`).join(''):'<div class="notice">No saved Temple recent-unlock feed yet.</div>'}
function bindGimTabs(){const buttons=$$('[data-gim-tab]'),panels=$$('[data-gim-panel]');buttons.forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.onclick=async()=>{buttons.forEach(x=>x.classList.toggle('active',x===b));panels.forEach(p=>p.classList.toggle('hidden',p.dataset.gimPanel!==b.dataset.gimTab));if(b.dataset.gimTab==='value')await renderClogValue();if(b.dataset.gimTab==='contribution'&&state.priceStatus==='loaded')renderClogContribution()}});for(const id of ['clogSearch','clogStatus','clogSort']){const e=$('#'+id);if(e&&!e.dataset.bound){e.dataset.bound='1';e.addEventListener(id==='clogSearch'?'input':'change',()=>{clogPage=0;renderClogItems()})}}}
function parseClogHunter(j,target){const root=j?.collectionLog||j?.collection_log||j;if(!root?.tabs)throw new Error('No Collection Log tabs found.');const items=[];function walk(n){if(Array.isArray(n)){n.forEach(walk);return}if(!n||typeof n!=='object')return;if(Number.isFinite(+(n.id??n.itemId))){items.push({id:+(n.id??n.itemId),name:n.name||n.itemName,count:+(n.count??n.quantity??(n.obtained?1:0))||0,date:n.date||null});return}Object.values(n).forEach(walk)}walk(root.tabs);if(items.length<20)throw new Error('Import looks incomplete.');const p=playerByKey(target);return{data:{player:p.name,player_name_with_capitalization:p.name,items,total_collections_in_response:items.length,total_collections_finished:items.filter(x=>x.count>0).length,total_collections_available:Math.max(items.length,collectionModel().known)}}}
function bindRecovery(){const input=$('#clogImport');if(input&&!input.dataset.bound){input.dataset.bound='1';input.onchange=async()=>{try{const file=input.files?.[0];if(!file)return;const j=JSON.parse(await file.text()),target=$('#clogImportTarget')?.value||'dikste';if(j?.players){state.temple=j}else if(validTemple(j)){state.temple={...(state.temple||{}),players:{...(state.temple?.players||{}),[target]:j},fetchedAt:Date.now()}}else{const p=parseClogHunter(j,target);state.temple={...(state.temple||{}),players:{...(state.temple?.players||{}),[target]:p},fetchedAt:Date.now()}}saveJSON(TKEY,state.temple);setNotice('Browser-only Collection Log import applied. Shared GitHub data was not changed.','');renderMast();renderGim()}catch(e){setNotice('Import failed: '+esc(e.message||e),'warn')}finally{input.value=''}}}const ex=$('#clogExport');if(ex&&!ex.dataset.bound){ex.dataset.bound='1';ex.onclick=()=>{const blob=new Blob([JSON.stringify(state.temple,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`united-gimps-collection-log-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}}const reset=$('#clogReset');if(reset&&!reset.dataset.bound){reset.dataset.bound='1';reset.onclick=async()=>{localStorage.removeItem(TKEY);await loadTempleSaved({discardBrowser:true});renderMast();renderGim();setNotice('Browser Collection Log override cleared; shared saved Temple snapshot restored.','')}}}
function cachedNearest(p,target){const arr=snapshotsFor(p.key);if(!arr.length)return null;const snap=arr.reduce((best,s)=>Math.abs(+new Date(s.createdAt)-target)<Math.abs(+new Date(best.createdAt)-target)?s:best,arr[0]);return{snap,diffDays:Math.abs(+new Date(snap.createdAt)-target)/864e5,source:'saved WOM snapshot'}}
async function findNearestSnapshot(p,target,allowNetwork=true){const saved=cachedNearest(p,+target);if(saved&&saved.diffDays<=90)return saved;if(!allowNetwork)return saved||{snap:null,diffDays:null};const spans=[45,180,730];for(const span of spans){const start=new Date(+target-span*864e5),end=new Date(+target+span*864e5);try{const j=await fetchJSON(`${API}/players/${encodeURIComponent(p.name)}/snapshots?startDate=${encodeURIComponent(start.toISOString())}&endDate=${encodeURIComponent(end.toISOString())}&limit=50&offset=0`,{attempts:2}),arr=Array.isArray(j)?j:[];if(arr.length){const snap=arr.reduce((best,s)=>Math.abs(+new Date(s.createdAt)-+target)<Math.abs(+new Date(best.createdAt)-+target)?s:best,arr[0]),diffDays=Math.abs(+new Date(snap.createdAt)-+target)/864e5;return{snap,diffDays,source:'WOM request you explicitly triggered'}}}catch(e){console.warn('time machine',p.name,e)}await sleep(150)}return saved||{snap:null,diffDays:null}}
function quality(diff){if(diff==null)return['approx','No datapoint'];if(diff<.6)return['exact','Same day'];if(diff<=7)return['near',`${Math.round(diff)} days away`];return['approx',`${Math.round(diff)} days away`]}
async function runTimeMachine(dateStr){const target=new Date(`${dateStr}T12:00:00`);if(Number.isNaN(+target))return;const go=$('#timeGo');if(go){go.disabled=true;go.textContent='Searching saved WOM history…'}setNotice('Using saved WOM snapshots first. If the saved history is not close enough, this explicit Time Machine request may ask WOM for a historical datapoint.','warn');const res={};for(const p of PLAYERS){res[p.key]=await findNearestSnapshot(p,target,true);await sleep(100)}renderTimeResults(target,res);setNotice('');if(go){go.disabled=false;go.textContent='Enter the time machine'}}
function renderTimeResults(target,res){const title=$('#timeResultBanner');if(title)title.innerHTML=`<strong>TIME MACHINE · ${dateOnly(target)}</strong><span>Nearest real WOM datapoints only. Nothing between snapshots is interpolated.</span>`;const host=$('#timeCore');if(host)host.innerHTML=CORE.map(p=>timeCard(p,res[p.key])).join('');const side=$('#timeSide');if(side)side.innerHTML=SIDE.map(p=>timeCard(p,res[p.key],true)).join('');renderTimeStanding(res);renderTimeSkills(res);renderTimeBosses(res)}
function timeCard(p,r,side=false){const s=r?.snap,o=s?.data?.skills?.overall||{},now=overall(p.key),ehp=+s?.data?.computed?.ehp?.value,ehb=+s?.data?.computed?.ehb?.value,[qc,ql]=quality(r?.diffDays);if(!s)return `<article class="${side?'side-card':'time-card'}" style="--pc:${p.color}"><div><h3>${p.name}</h3><div class="muted">No WOM snapshot found around this date.</div></div></article>`;return `<article class="time-card" style="--pc:${p.color};${side?'opacity:.76':''}"><div class="snap-date">Actual WOM snapshot ${dateTime(s.createdAt)}</div><h3>${p.name}</h3><div class="time-metrics"><div class="time-metric"><span>Total level</span><b>${fmt(o.level)}</b><em>→ now ${fmt(now.level)} · ${(+now.level||0)-(+o.level||0)>=0?'+':''}${fmt((+now.level||0)-(+o.level||0))}</em></div><div class="time-metric"><span>Total XP</span><b>${compact(o.experience)}</b><em>→ +${compact((+now.experience||0)-(+o.experience||0))}</em></div><div class="time-metric"><span>EHP</span><b>${fmt1(ehp)}</b><em>→ ${fmt1(currentComputed(p.key,'ehp'))}</em></div><div class="time-metric"><span>EHB</span><b>${fmt1(ehb)}</b><em>→ ${fmt1(currentComputed(p.key,'ehb'))}</em></div></div><span class="quality ${qc}">${ql} · ${esc(r.source||'WOM')}</span></article>`}
function renderTimeStanding(res){const t=$('#timeStanding');if(!t)return;const rows=[['Total level',p=>+res[p.key]?.snap?.data?.skills?.overall?.level],['Total XP',p=>+res[p.key]?.snap?.data?.skills?.overall?.experience],['EHP',p=>+res[p.key]?.snap?.data?.computed?.ehp?.value],['EHB',p=>+res[p.key]?.snap?.data?.computed?.ehb?.value]];let h='<thead><tr><th>Metric</th>'+CORE.map(p=>`<th>${p.name}</th>`).join('')+'</tr></thead><tbody>';for(const [l,f] of rows){const vals=CORE.map(f),r=rankValues(vals);h+=`<tr><td>${l}</td>${vals.map((v,i)=>rankCell(l==='Total XP'?compact(v):l.startsWith('E')?fmt1(v):fmt(v),r[i])).join('')}</tr>`}t.innerHTML=h+'</tbody>'}
function renderTimeSkills(res){const t=$('#timeSkills');if(!t)return;const ks=new Set();CORE.forEach(p=>Object.keys(res[p.key]?.snap?.data?.skills||{}).forEach(k=>{if(k!=='overall')ks.add(k)}));let h='<thead><tr><th>Skill</th>'+CORE.map(p=>`<th>${p.name}</th>`).join('')+'</tr></thead><tbody>';for(const k of ks){const vals=CORE.map(p=>+res[p.key]?.snap?.data?.skills?.[k]?.experience||0),r=rankValues(vals);h+=`<tr><td>${nice(k)}</td>${CORE.map((p,i)=>{const x=res[p.key]?.snap?.data?.skills?.[k];return rankCell(x?`Lv ${fmt(x.level)} · ${compact(x.experience)}`:'—',r[i])}).join('')}</tr>`}t.innerHTML=h+'</tbody>'}
function renderTimeBosses(res){const t=$('#timeBosses');if(!t)return;const ks=new Set();CORE.forEach(p=>Object.keys(res[p.key]?.snap?.data?.bosses||{}).forEach(k=>{if(CORE.some(q=>(+res[q.key]?.snap?.data?.bosses?.[k]?.kills||0)>0))ks.add(k)}));const rows=[...ks].map(k=>({k,vals:CORE.map(p=>Math.max(0,+res[p.key]?.snap?.data?.bosses?.[k]?.kills||0))})).sort((a,b)=>Math.max(...b.vals)-Math.max(...a.vals)).slice(0,50);let h='<thead><tr><th>Boss</th>'+CORE.map(p=>`<th>${p.name}</th>`).join('')+'</tr></thead><tbody>';for(const x of rows){const r=rankValues(x.vals);h+=`<tr><td>${nice(x.k)}</td>${x.vals.map((v,i)=>rankCell(fmt(v),r[i])).join('')}</tr>`}t.innerHTML=h+'</tbody>'}
function renderTimeMachine(){const inp=$('#timeDate');if(!inp)return;inp.max=new Date().toISOString().slice(0,10);if(!inp.value){const d=new Date();d.setFullYear(d.getFullYear()-1);inp.value=d.toISOString().slice(0,10)}$('#timeGo').onclick=()=>runTimeMachine(inp.value);$$('[data-time-preset]').forEach(b=>b.onclick=()=>{const v=b.dataset.timePreset;if(v==='1y'){const d=new Date();d.setFullYear(d.getFullYear()-1);inp.value=d.toISOString().slice(0,10)}else if(v==='6m'){const d=new Date();d.setMonth(d.getMonth()-6);inp.value=d.toISOString().slice(0,10)}else inp.value=v;runTimeMachine(inp.value)});const banner=$('#timeResultBanner');if(banner)banner.innerHTML='<strong>READY</strong><span>No WOM request has been made. Pick a date to use saved history first.</span>'}
function milestoneEvent(p,date,name,metric,score=3){return{type:'achievement',player:p.name,key:p.key,core:p.core,date:+new Date(date),name,metric,measure:'tracker_derived',accuracy:0,score,source:'WOM snapshot'}}
function derivedMilestones(p){const arr=snapshotsFor(p.key),out=[];if(arr.length<2)return out;const skillLevels=[70,80,90,95,99],bossMarks=[25,50,100,250,500,1000,2000],totalMarks=[1000,1250,1500,1750,2000,2100,2200,2300,2350,2376],xpMarks=[10e6,20e6,30e6,50e6,75e6,100e6,150e6,200e6,300e6,500e6,750e6,1e9];for(let i=1;i<arr.length;i++){const a=arr[i-1],b=arr[i],ad=a.data||{},bd=b.data||{},date=b.createdAt;const al=+ad.skills?.overall?.level||0,bl=+bd.skills?.overall?.level||0;const tm=totalMarks.filter(x=>al<x&&bl>=x).at(-1);if(tm)out.push(milestoneEvent(p,date,`${fmt(tm)} total level`,'overall',tm>=2300?7:tm>=2000?5:3));const ax=+ad.skills?.overall?.experience||0,bx=+bd.skills?.overall?.experience||0,xm=xpMarks.filter(x=>ax<x&&bx>=x).at(-1);if(xm)out.push(milestoneEvent(p,date,`${compact(xm)} total XP`,'overall',xm>=200e6?7:xm>=100e6?5:3));for(const [k,v] of Object.entries(bd.skills||{})){if(k==='overall')continue;const av=+ad.skills?.[k]?.level||0,bv=+v.level||0,sm=skillLevels.filter(x=>av<x&&bv>=x).at(-1);if(sm)out.push(milestoneEvent(p,date,`${sm} ${nice(k)}` ,k,sm===99?8:sm>=95?6:sm>=90?5:sm>=80?4:3))}for(const [k,v] of Object.entries(bd.bosses||{})){const av=Math.max(0,+ad.bosses?.[k]?.kills||0),bv=Math.max(0,+v.kills||0),bm=bossMarks.filter(x=>av<x&&bv>=x).at(-1);if(bm)out.push(milestoneEvent(p,date,`${fmt(bm)} ${nice(k)} KC`,k,bm>=1000?8:bm>=500?7:bm>=250?6:bm>=100?5:bm>=50?4:3))}}return out}
function officialAchievements(){const out=[];for(const p of PLAYERS){const a=state.achievements?.[p.key]||[];for(const x of Array.isArray(a)?a:[]){const d=x.createdAt||x.date;if(!d)continue;out.push({type:'achievement',player:p.name,key:p.key,core:p.core,date:+new Date(d),name:x.name||x.title||`${nice(x.metric)} milestone`,metric:x.metric,measure:x.measure,accuracy:+x.accuracy||0,score:achievementScore(x),source:'WOM achievement'})}}return out}
function achievementScore(x){const s=String(x.name||'').toLowerCase(),n=+(s.match(/\d[\d,]*/)?.[0]||'0').replace(/,/g,'');if(/99\b/.test(s))return 9;if(/200m|100m/.test(s))return 9;if(n>=1000)return 8;if(n>=500)return 7;if(n>=250)return 6;if(n>=100)return 5;if(n>=50)return 4;if(n>=25)return 3;return 2}
function chronicleEvents(){const all=[...officialAchievements(),...PLAYERS.flatMap(derivedMilestones)];for(const d of templeRecent()){const key=playerKey(d.player),p=playerByKey(key);all.push({type:'drop',player:d.player||p?.name||'Group',key,core:p?.core??false,date:d.date,name:d.name,itemId:d.id,notable:d.notable,score:d.notable?9:3,source:'Temple recent collection'})}all.sort((a,b)=>b.date-a.date);const seen=new Set();return all.filter(e=>{const bucket=Math.round(e.date/864e5),sig=`${e.key}|${e.type}|${String(e.name).toLowerCase()}|${bucket}`;if(seen.has(sig))return false;seen.add(sig);return true})}
function balancedHighlights(ev){const by=new Map(PLAYERS.map(p=>[p.key,[]]));for(const e of ev)if(by.has(e.key))by.get(e.key).push(e);const chosen=[];for(const p of PLAYERS){const arr=by.get(p.key).sort((a,b)=>(b.score-a.score)||(b.date-a.date)),quota=p.core?18:8;chosen.push(...arr.slice(0,quota))}const must=ev.filter(e=>e.score>=8).slice(0,30);const map=new Map([...chosen,...must].map(e=>[`${e.key}|${e.type}|${e.name}|${e.date}`,e]));return[...map.values()].sort((a,b)=>b.date-a.date).slice(0,75)}
async function refreshChronicleWom(){const achievements={...state.achievements};for(const p of PLAYERS){try{const a=await fetchJSON(`${API}/players/${encodeURIComponent(p.name)}/achievements`,{attempts:2});if(Array.isArray(a))achievements[p.key]=a}catch(e){console.warn('achievements',p.name,e)}await sleep(300)}state.achievements=achievements;const old=loadJSON(WKEY)||{};saveJSON(WKEY,{...old,fetchedAt:Date.now(),profiles:state.profiles,gains:state.gains,snapshots:state.snapshots,achievements});saveJSON(CKEY,{savedAt:Date.now(),events:chronicleEvents()})}
function nextMark(v,marks){return marks.find(x=>x>v)}
function trackerGoals(p){const goals=[],o=overall(p.key),tl=+o.level||0,tm=nextMark(tl,[1000,1250,1500,1750,2000,2100,2200,2300,2350,2376]);if(tm)goals.push({label:`${fmt(tm)} total level`,left:tm-tl,source:'WOM stats'});const skills=Object.entries(snapData(p.key)?.skills||{}).filter(([k])=>k!=='overall').map(([k,v])=>({k,l:+v.level||0})),cands=[];for(const s of skills){const n=nextMark(s.l,[70,80,90,95,99]);if(n)cands.push({label:`${n} ${nice(s.k)}`,left:n-s.l,source:'WOM stats'})}cands.sort((a,b)=>a.left-b.left);goals.push(...cands.slice(0,2));const bosses=Object.entries(snapData(p.key)?.bosses||{}).map(([k,v])=>({k,c:Math.max(0,+v.kills||0)})).filter(x=>x.c>0),bc=[];for(const b of bosses){const n=nextMark(b.c,[25,50,100,250,500,1000,2000]);if(n)bc.push({label:`${fmt(n)} ${nice(b.k)} KC`,left:n-b.c,source:'WOM stats'})}bc.sort((a,b)=>a.left-b.left);if(bc[0])goals.push(bc[0]);const m=collectionModel();if(m.keys.includes(p.key)){const own=m.union.filter(r=>r.owners[p.key]).length,n=Math.ceil((own+1)/25)*25;goals.push({label:`${n} personal Collection Log uniques`,left:n-own,source:'Temple Collection Log'})}return goals.slice(0,4)}
function renderGoals(){const h=$('#chronicleGoals');if(!h)return;h.innerHTML=PLAYERS.map(p=>`<article class="goal-card ${p.core?'':'side'}" style="--pc:${p.color}"><div class="goal-head"><img src="${p.portrait}" alt=""><h3>${p.name}</h3></div>${trackerGoals(p).map(g=>`<div class="goal-line"><span>${esc(g.label)}</span><b>${fmt(g.left)} away</b><small>${esc(g.source)} · tracker-derived goal</small></div>`).join('')||'<div class="muted">No nearby saved-data goal found.</div>'}</article>`).join('')}
let chronoFilter='highlights';async function renderChronicle(){const host=$('#chronicle');if(!host)return;let ev=chronicleEvents();if(chronoFilter==='highlights')ev=balancedHighlights(ev);else if(chronoFilter==='milestones')ev=ev.filter(e=>e.type==='achievement');else if(chronoFilter==='drops')ev=ev.filter(e=>e.type==='drop');else if(chronoFilter==='core')ev=ev.filter(e=>e.core);else if(chronoFilter==='side')ev=ev.filter(e=>!e.core);ev=ev.slice(0,600);let year=null,h='';for(const e of ev){const y=new Date(e.date).getFullYear();if(y!==year){h+=`<div class="chronicle-year">${y}</div>`;year=y}const side=e.core===false?'side':'',notable=e.notable||e.score>=8?'notable':'';h+=`<article class="chronicle-event ${side} ${notable}"><div class="chronicle-date">${dateTime(e.date)}${e.accuracy>0?` · WOM accuracy ±${Math.round(e.accuracy/36e5)}h`:''}</div><div class="chronicle-main">${e.type==='drop'?`<img src="https://static.runelite.net/cache/item/icon/${e.itemId}.png" alt="">`:''}<div><h4>${esc(e.player)} · ${esc(e.name)}</h4><p>${e.type==='drop'?'Drop / item unlock via Temple':'Stats milestone via WOM'}${e.source==='WOM snapshot'?' · derived from saved snapshot crossing':''}${side?' · supporting cast':''}</p></div></div></article>`}host.innerHTML=h||'<div class="notice">No Chronicle events matched this filter.</div>';const meta=$('#chronicleMeta');if(meta)meta.textContent=`${ev.length} events shown · stats milestones via WOM + drops/item unlocks via Temple`;renderGoals();$$('[data-chrono-filter]').forEach(b=>b.classList.toggle('active',b.dataset.chronoFilter===chronoFilter))}
function bindChronicle(){const refresh=$('#chronicleRefresh');if(refresh&&!refresh.dataset.bound){refresh.dataset.bound='1';refresh.onclick=async()=>{refresh.disabled=true;const old=refresh.textContent;refresh.textContent='Refreshing WOM milestones…';setNotice('Refreshing Chronicle stats milestones via WOM because you explicitly requested it.','warn');await refreshChronicleWom();await renderChronicle();setNotice('Chronicle WOM milestone refresh complete for this browser.','');refresh.disabled=false;refresh.textContent=old}}$$('[data-chrono-filter]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.onclick=()=>{chronoFilter=b.dataset.chronoFilter;renderChronicle()}})}
const ERA_FAMS={Raids:['chambers_of_xeric','chambers_of_xeric_challenge_mode','theatre_of_blood','theatre_of_blood_hard_mode','tombs_of_amascut','tombs_of_amascut_expert'],Gauntlet:['the_gauntlet','the_corrupted_gauntlet'],DT2:['duke_sucellus','the_leviathan','the_whisperer','vardorvis'],Slayer:['abyssal_sire','alchemical_hydra','cerberus','kraken','thermonuclear_smoke_devil','grotesque_guardians'],GWD:['commander_zilyana','general_graardor','kreearra','kril_tsutsaroth','nex'],Wilderness:['callisto','vetion','venenatis','artio','calvarion','spindel','chaos_elemental','chaos_fanatic','crazy_archaeologist','scorpia']};
function eraDelta(a,b){const xp=Math.max(0,(+b.data?.skills?.overall?.experience||0)-(+a.data?.skills?.overall?.experience||0)),levels=Math.max(0,(+b.data?.skills?.overall?.level||0)-(+a.data?.skills?.overall?.level||0)),fam={};let boss=0;for(const [name,ks] of Object.entries(ERA_FAMS)){let n=0;for(const k of ks)n+=Math.max(0,(+b.data?.bosses?.[k]?.kills||0)-Math.max(0,+a.data?.bosses?.[k]?.kills||0));fam[name]=n;boss+=n}let type='Mixed progression';const best=Object.entries(fam).sort((x,y)=>y[1]-x[1])[0];if(best&&best[1]>=20)type=best[0];else if(boss>=50)type='General bossing';else if(xp>=1500000||levels>=10)type='Skilling';else if(xp<250000&&boss<10)type='Quiet / maintenance';return{start:a.createdAt,end:b.createdAt,type,evidence:`+${compact(xp)} XP · +${levels} levels · ${fmt(boss)} curated boss KC`}}
function playerEras(p){const arr=snapshotsFor(p.key);if(arr.length<2)return[];const raw=[];for(let i=1;i<arr.length;i++){const e=eraDelta(arr[i-1],arr[i]),last=raw.at(-1);if(last&&last.type===e.type){last.end=e.end;last.evidence=e.evidence}else raw.push(e)}return raw.slice(-12)}
function renderActivityEras(){const host=$('#activityEras');if(!host)return;const data=CORE.map(p=>({p,eras:playerEras(p)})),times=data.flatMap(x=>x.eras.flatMap(e=>[+new Date(e.start),+new Date(e.end)]));if(!times.length){host.innerHTML='<div class="notice">No saved WOM snapshot history is available yet. The next owner shared refresh will populate it.</div>';return}const min=Math.min(...times),max=Math.max(...times),span=Math.max(1,max-min);host.innerHTML=`<div class="era-shell"><div class="era-axis">${Array.from({length:5},(_,i)=>{const q=i/4,t=min+q*span;return `<i style="left:${q*100}%"><span>${dateOnly(t)}</span></i>`}).join('')}</div>${data.map(({p,eras})=>`<div class="era-lane"><div class="era-label"><img src="${p.portrait}" alt=""><b>${p.name}</b></div><div class="era-track">${eras.map(e=>{const l=(+new Date(e.start)-min)/span*100,w=(+new Date(e.end)-+new Date(e.start))/span*100;return `<div class="era-segment era-${e.type.toLowerCase().replace(/[^a-z]+/g,'-')}" style="left:${l}%;width:${Math.max(.7,w)}%" title="${esc(e.type+' · '+e.evidence)}"><strong>${esc(e.type)}</strong><small>${esc(e.evidence)}</small></div>`}).join('')}</div></div>`).join('')}<div class="era-note">Tracker inference from saved WOM changes. The label is ours, the underlying XP/level/KC datapoints are WOM.</div></div>`}
function renderHistory(){const host=$('#historyCoverage');if(host)host.innerHTML=PLAYERS.map(p=>{const arr=snapshotsFor(p.key);return `<div class="kpi ${p.core?'':'side-kpi'}"><span>${p.name}${p.core?'':' · side'}</span><b>${arr.length?fmt(arr.length)+' snapshots':'—'}</b><small>${arr.length?`${dateOnly(arr[0].createdAt)} → ${dateOnly(arr.at(-1).createdAt)}`:'no saved history yet'}</small></div>`}).join('');const c=$('#historyCta');if(c)c.innerHTML='<a class="btn" href="time-machine.html">Open Time Machine →</a> <a class="btn" href="chronicle.html">Open Chronicle →</a>';renderActivityEras()}
let modal=null;function ensureModal(){if(modal)return modal;modal=document.createElement('div');modal.className='modal';modal.hidden=true;modal.innerHTML=`<div class="modal-dialog"><div class="modal-head"><div><div class="eyebrow">THREE-PLAYER SKILL HISTORY</div><h2 id="modalTitle"></h2><div class="section-note">Core trio overlaid from saved WOM snapshot history. No silent WOM fetch.</div></div><button class="modal-close">Close</button></div><div class="modal-periods">${[['all','All'],[365,'1Y'],[180,'6M'],[90,'3M'],[30,'1M'],[7,'1W']].map(([r,l])=>`<button data-modal-range="${r}">${l}</button>`).join('')}</div><div id="modalStatus" class="notice"></div><div id="modalChart" class="skill-modal-chart"></div><div class="legend">${CORE.map(p=>`<span><i style="background:${p.color}"></i>${p.name}</span>`).join('')}</div></div>`;document.body.append(modal);$('.modal-close',modal).onclick=()=>modal.hidden=true;modal.onclick=e=>{if(e.target===modal)modal.hidden=true;const b=e.target.closest('[data-modal-range]');if(b)renderSkillModal(modal.dataset.skill,b.dataset.modalRange)};document.addEventListener('keydown',e=>{if(e.key==='Escape')modal.hidden=true});return modal}
function skillTimeline(p,skill,range){let arr=snapshotsFor(p.key);if(range!=='all'){const days=+range,end=arr.length?+new Date(arr.at(-1).createdAt):Date.now();arr=arr.filter(s=>+new Date(s.createdAt)>=end-days*864e5)}return arr.map(s=>({date:s.createdAt,value:+s.data?.skills?.[skill]?.experience})).filter(x=>Number.isFinite(x.value)&&x.value>=0)}
async function openSkill(skill,recent=false){const m=ensureModal();m.dataset.skill=skill;m.hidden=false;$('#modalTitle',m).textContent=nice(skill)+' XP';renderSkillModal(skill,recent?String(state.period):'all')}
function renderSkillModal(skill,range){const m=ensureModal();$$('[data-modal-range]',m).forEach(b=>b.classList.toggle('active',b.dataset.modalRange===String(range)));const series=CORE.map(p=>({name:p.name,color:p.color,data:skillTimeline(p,skill,range)}));drawLine($('#modalChart',m),series);$('#modalStatus',m).textContent=`${series.reduce((n,s)=>n+s.data.length,0)} saved WOM timeline datapoints · no new WOM request.`}
function globalClicks(){document.addEventListener('click',e=>{const s=e.target.closest('[data-skill]');if(s){e.preventDefault();openSkill(s.dataset.skill,s.dataset.recent==='1')}})}
async function renderPage(){renderMast();updateDataStatus();const pg=document.body.dataset.page;if(pg==='home')renderOverview();else if(pg==='hiscores')renderHiscores();else if(pg==='progress')await renderProgress();else if(pg==='gim')renderGim();else if(pg==='history')renderHistory();else if(pg==='time')renderTimeMachine();else if(pg==='chronicle'){bindChronicle();await renderChronicle()}}
async function init(){bindCommon();globalClicks();await Promise.all([loadTempleSaved(),loadWomSaved()]);$$('[data-period-button]').forEach(x=>x.classList.toggle('active',+x.dataset.periodButton===state.period));await renderPage()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
